"use client"

import { useState, useEffect, useCallback } from "react"
import { ArrowLeft, Copy, Download, Loader2, CheckCircle2, RefreshCw, XCircle } from "lucide-react"
import Link from "next/link"
import { useParams } from "next/navigation"
import { toast } from "sonner"

import { cancelBulkmailOrder, exportBulkmailOrder, getBulkmailOrder, listAllOrders } from "@/app/actions/admin"
import { ClientDate } from "@/components/client-date"
import { copyToClipboard } from "@/lib/clipboard"
import { formatLineTotal } from "@/lib/format"
import { exportCredentialsTxt, parseCredentialAccounts, toPipeLine, PIPE_FORMAT_HINT } from "@/lib/credentials"

type OrderRow = {
  id: number
  userEmail: string
  productName: string
  price: number
  quantity: number
  status: string
  supplier?: string
  externalOrderId?: string
  purchasedAt: string
  deliveredEmail: string
  deliveredPassword: string
  deliveredRefreshToken: string
  deliveredClientId: string
  deliveredCredentials: string
}

type SupplierOrder = {
  id: number
  orderNumber: string
  productName: string
  quantity: number
  unitPrice: number
  totalAmount: number
  unitPriceBdt: number
  totalAmountBdt: number
  status: string
  createdAt: string
  stockItems: string[]
  currency: string
}

export default function AdminOrderDetailsPage() {
  const { id } = useParams<{ id: string }>()
  const [orders, setOrders] = useState<OrderRow[] | null>(null)
  const [loading, setLoading] = useState(true)
  const [loadError, setLoadError] = useState<string | null>(null)

  useEffect(() => {
    let cancelled = false
    listAllOrders()
      .then((data) => {
        if (cancelled) return
        setOrders(data as OrderRow[])
        setLoading(false)
      })
      .catch((error) => {
        if (cancelled) return
        setLoadError(error instanceof Error ? error.message : "Could not load orders.")
        setLoading(false)
      })
    return () => {
      cancelled = true
    }
  }, [])

  const order = orders?.find((o) => String(o.id) === id)

  const isBulkmail = (order?.supplier ?? "hotmail143").toLowerCase() === "bulkmail"
  const supplierNumericId =
    isBulkmail && order?.externalOrderId && /^\d+$/.test(order.externalOrderId)
      ? Number(order.externalOrderId)
      : null

  const [supplierOrder, setSupplierOrder] = useState<SupplierOrder | null>(null)
  const [supplierLoading, setSupplierLoading] = useState(false)
  const [supplierError, setSupplierError] = useState<string | null>(null)
  const [exporting, setExporting] = useState<string | null>(null)
  const [cancelling, setCancelling] = useState(false)

  const loadSupplierOrder = useCallback(async () => {
    if (supplierNumericId == null) return
    setSupplierLoading(true)
    setSupplierError(null)
    const res = await getBulkmailOrder(supplierNumericId)
    setSupplierLoading(false)
    if (res.ok) setSupplierOrder(res)
    else {
      setSupplierError(res.message)
      setSupplierOrder(null)
    }
  }, [supplierNumericId])

  useEffect(() => {
    if (isBulkmail && supplierNumericId != null) void loadSupplierOrder()
  }, [isBulkmail, supplierNumericId, loadSupplierOrder])

  async function handleExport(format: "txt" | "csv" | "json") {
    if (supplierNumericId == null) return
    setExporting(format)
    const res = await exportBulkmailOrder(supplierNumericId, format)
    setExporting(null)
    if (!res.ok) {
      toast.error(res.message)
      return
    }
    const blob = new Blob([res.content], { type: res.contentType || "text/plain" })
    const url = URL.createObjectURL(blob)
    const a = document.createElement("a")
    a.href = url
    a.download = res.filename || `bulkmail-order-${supplierNumericId}.${format}`
    document.body.appendChild(a)
    a.click()
    a.remove()
    URL.revokeObjectURL(url)
    toast.success(`Exported ${res.filename || format.toUpperCase()}.`)
  }

  async function handleCancelSupplier() {
    if (supplierNumericId == null) return
    if (!window.confirm("Cancel this order at BulkMail? The refund goes to the supplier wallet — the local customer order is untouched.")) return
    setCancelling(true)
    const res = await cancelBulkmailOrder(supplierNumericId)
    setCancelling(false)
    if (!res.ok) {
      toast.error(res.message)
      return
    }
    toast.success(
      res.message || `Cancelled — refunded${res.refundedAmountBdt != null ? ` ${res.refundedAmountBdt}` : ""}.`,
    )
    await loadSupplierOrder()
  }

  const accounts = parseCredentialAccounts({
    deliveredCredentials: order?.deliveredCredentials,
    deliveredEmail: order?.deliveredEmail,
    deliveredPassword: order?.deliveredPassword,
    deliveredRefreshToken: order?.deliveredRefreshToken,
    deliveredClientId: order?.deliveredClientId,
  })

  async function copyLine(line: string) {
    if (!line) return
    const ok = await copyToClipboard(line)
    if (ok) toast.success("Line copied.")
    else toast.error("Could not copy to clipboard.")
  }

  async function copyAll() {
    if (accounts.length === 0) return
    const ok = await copyToClipboard(accounts.map(toPipeLine).join("\n"))
    if (ok) toast.success(`${accounts.length} line${accounts.length === 1 ? "" : "s"} copied.`)
    else toast.error("Could not copy to clipboard.")
  }

  function exportTxt() {
    if (!order || accounts.length === 0) return
    exportCredentialsTxt(`order-${id}-credentials.txt`, accounts)
  }

  if (loading) {
    return (
      <div className="flex flex-col gap-6">
        <Link href="/admin/orders" className="inline-flex items-center gap-1.5 text-sm text-muted-foreground hover:text-foreground">
          <ArrowLeft className="size-4" /> Back to orders
        </Link>
        <p className="text-muted-foreground">Loading…</p>
      </div>
    )
  }

  if (loadError) {
    return (
      <div className="flex flex-col gap-6">
        <Link href="/admin/orders" className="inline-flex items-center gap-1.5 text-sm text-muted-foreground hover:text-foreground">
          <ArrowLeft className="size-4" /> Back to orders
        </Link>
        <p className="text-red-400">Could not load order: {loadError}</p>
      </div>
    )
  }

  if (!order) {
    return (
      <div className="flex flex-col gap-6">
        <Link href="/admin/orders" className="inline-flex items-center gap-1.5 text-sm text-muted-foreground hover:text-foreground">
          <ArrowLeft className="size-4" /> Back to orders
        </Link>
        <p className="text-muted-foreground">Order not found.</p>
      </div>
    )
  }

  return (
    <div key={id} className="flex flex-col gap-5">
      <Link href="/admin/orders" className="inline-flex items-center gap-1.5 text-sm text-muted-foreground hover:text-foreground">
        <ArrowLeft className="size-4" /> Back to orders
      </Link>

      <div>
        <h1 className="text-xl font-semibold text-foreground">Order Details</h1>
        <p className="mt-1 text-sm text-muted-foreground">Customer credentials and delivery info.</p>
      </div>

      <div className="rounded-xl border border-border bg-card p-4">
        <div className="grid grid-cols-2 gap-3 text-sm sm:grid-cols-4">
          <div>
            <p className="text-muted-foreground">Customer</p>
            <p className="font-medium text-foreground">{order.userEmail}</p>
          </div>
          <div>
            <p className="text-muted-foreground">Product</p>
            <p className="font-medium text-foreground">{order.productName}</p>
          </div>
          <div>
            <p className="text-muted-foreground">Qty</p>
            <p className="font-medium text-foreground">{order.quantity ?? 1}</p>
          </div>
          <div>
            <p className="text-muted-foreground">Total</p>
            <p className="font-medium text-foreground">{formatLineTotal(order.price ?? 0, order.quantity)}</p>
          </div>
          <div>
            <p className="text-muted-foreground">Status</p>
            {(() => {
              const s = (order.status ?? "").toString().toLowerCase()
              if (s === "completed") return (
                <span className="inline-flex items-center gap-1.5 rounded-full bg-emerald-500/15 px-2 py-0.5 text-xs font-medium text-emerald-400">
                  <CheckCircle2 className="size-3" />
                  Completed
                </span>
              )
              if (s === "processing" || s === "pending") return (
                <span className="inline-flex items-center gap-1.5 rounded-full bg-amber-500/15 px-2 py-0.5 text-xs font-medium text-amber-400">
                  <Loader2 className="size-3 animate-spin text-amber-400" />
                  Processing
                </span>
              )
              if (s === "failed") return (
                <span className="inline-flex items-center gap-1.5 rounded-full bg-red-500/15 px-2 py-0.5 text-xs font-medium text-red-400">
                  Failed
                </span>
              )
              return (
                <span className="inline-flex items-center gap-1.5 rounded-full bg-muted px-2 py-0.5 text-xs font-medium text-muted-foreground capitalize">
                  {order.status ?? "unknown"}
                </span>
              )
            })()}
          </div>
          <div>
            <p className="text-muted-foreground">Date</p>
            <p className="font-medium text-foreground"><ClientDate iso={order.purchasedAt} /></p>
          </div>
          <div>
            <p className="text-muted-foreground">Supplier</p>
            <p className="font-medium font-mono text-xs text-foreground">{order.supplier ?? "hotmail143"}</p>
          </div>
          <div>
            <p className="text-muted-foreground">Supplier order</p>
            <p className="font-medium font-mono text-xs text-foreground">{order.externalOrderId || "—"}</p>
          </div>
        </div>
      </div>

      {isBulkmail && (
        <div className="rounded-xl border border-border bg-card p-4">
          <div className="flex items-center justify-between gap-3">
            <div>
              <h2 className="text-sm font-semibold text-foreground">Supplier order (BulkMail)</h2>
              <p className="text-xs text-muted-foreground">Live purchase record at the supplier — view, re-export stock, or cancel while pending.</p>
            </div>
            <button
              type="button"
              onClick={() => void loadSupplierOrder()}
              disabled={supplierLoading || supplierNumericId == null}
              className="inline-flex items-center gap-1.5 rounded-md border border-border bg-background px-3 py-1.5 text-xs font-medium text-foreground hover:bg-muted disabled:opacity-50"
            >
              <RefreshCw className={`size-3 ${supplierLoading ? "animate-spin" : ""}`} />
              Refresh
            </button>
          </div>

          {supplierNumericId == null ? (
            <p className="mt-3 text-xs text-amber-400">No numeric supplier order id stored for this order — supplier actions unavailable.</p>
          ) : supplierLoading && !supplierOrder ? (
            <p className="mt-3 text-xs text-muted-foreground">Loading supplier order…</p>
          ) : supplierError && !supplierOrder ? (
            <p className="mt-3 text-xs text-red-400">{supplierError}</p>
          ) : supplierOrder ? (
            <div className="mt-3">
              <div className="grid grid-cols-2 gap-3 text-sm sm:grid-cols-4">
                <div>
                  <p className="text-muted-foreground">Order number</p>
                  <p className="font-mono text-xs font-medium text-foreground">{supplierOrder.orderNumber}</p>
                </div>
                <div>
                  <p className="text-muted-foreground">Supplier status</p>
                  <p className="font-medium text-foreground capitalize">{supplierOrder.status}</p>
                </div>
                <div>
                  <p className="text-muted-foreground">Qty</p>
                  <p className="font-medium text-foreground">{supplierOrder.quantity}</p>
                </div>
                <div>
                  <p className="text-muted-foreground">Supplier total</p>
                  <p className="font-medium text-foreground">
                    ${supplierOrder.totalAmount.toFixed(2)}{" "}
                    <span className="text-muted-foreground">
                      ≈ {supplierOrder.currency} {supplierOrder.totalAmountBdt.toFixed(2)}
                    </span>
                  </p>
                </div>
              </div>
              <p className="mt-2 text-[11px] text-muted-foreground">
                {supplierOrder.stockItems.length} stock item(s) at supplier · credentials already stored locally above.
              </p>
              <div className="mt-3 flex flex-wrap gap-2">
                {(["txt", "csv", "json"] as const).map((fmt) => (
                  <button
                    key={fmt}
                    type="button"
                    onClick={() => void handleExport(fmt)}
                    disabled={exporting !== null}
                    className="inline-flex items-center gap-1.5 rounded-md border border-border bg-background px-3 py-1.5 text-xs font-medium text-foreground hover:bg-muted disabled:opacity-50"
                  >
                    <Download className="size-3" />
                    {exporting === fmt ? "Exporting…" : `Export ${fmt.toUpperCase()}`}
                  </button>
                ))}
                {supplierOrder.status.toLowerCase() === "pending" && (
                  <button
                    type="button"
                    onClick={() => void handleCancelSupplier()}
                    disabled={cancelling}
                    className="inline-flex items-center gap-1.5 rounded-md border border-red-500/30 bg-red-500/10 px-3 py-1.5 text-xs font-medium text-red-300 hover:bg-red-500/20 disabled:opacity-50"
                  >
                    <XCircle className="size-3" />
                    {cancelling ? "Cancelling…" : "Cancel at supplier"}
                  </button>
                )}
              </div>
              <p className="mt-2 text-[11px] text-muted-foreground">
                Cancelling refunds the supplier wallet only — the local customer order is untouched.
              </p>
            </div>
          ) : null}
        </div>
      )}

      {accounts.length > 0 && (
        <div className="rounded-xl border border-border bg-card p-4">
          <div className="flex flex-wrap items-center justify-between gap-2">
            <h2 className="text-sm font-medium text-muted-foreground">
              Credentials ({accounts.length})
            </h2>
            <div className="flex items-center gap-2">
              <button
                type="button"
                onClick={copyAll}
                className="inline-flex items-center gap-1.5 rounded-md border border-border bg-background px-3 py-1.5 text-xs font-medium text-foreground hover:bg-muted"
              >
                <Copy className="size-3" />
                Copy all
              </button>
              <button
                type="button"
                onClick={exportTxt}
                className="inline-flex items-center gap-1.5 rounded-md border border-border bg-background px-3 py-1.5 text-xs font-medium text-foreground hover:bg-muted"
              >
                <Download className="size-3" />
                TXT
              </button>
            </div>
          </div>
          <p className="mt-2 font-mono text-[11px] text-muted-foreground">{PIPE_FORMAT_HINT}</p>

          <div className="mt-2 flex flex-col gap-2">
            {accounts.map((acc, i) => {
              const line = toPipeLine(acc)
              return (
                <div
                  key={i}
                  className="flex items-center gap-2 rounded-lg border border-border bg-background px-3 py-2.5"
                >
                  <span className="shrink-0 font-mono text-[11px] text-muted-foreground">{i + 1}</span>
                  <code className="min-w-0 flex-1 break-all font-mono text-xs text-foreground">{line}</code>
                  <button
                    type="button"
                    onClick={() => void copyLine(line)}
                    aria-label={`Copy line ${i + 1}`}
                    className="flex size-7 shrink-0 items-center justify-center rounded-md text-muted-foreground hover:bg-muted hover:text-foreground"
                  >
                    <Copy className="size-3.5" />
                  </button>
                </div>
              )
            })}
          </div>
        </div>
      )}

      {order.status === "processing" && accounts.length === 0 && (
        <div className="rounded-xl border border-border bg-card p-5 text-center">
          <p className="text-sm text-muted-foreground">Credentials will appear here once the order is delivered.</p>
        </div>
      )}
    </div>
  )
}
